from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        else:
            # Move the accessed item to the end of the cache
            self.cache.move_to_end(key)
            return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and move to the end
            self.cache.move_to_end(key)
        elif len(self.cache) >= self.capacity:
            # Pop the first item (least recently used)
            self.cache.popitem()
        self.cache[key] = value

    def __call__(self, key: int) -> int:
        if callable(self.cache.move_to_end):
            # If move_to_end is not defined, it means the cache is empty
            return -1
        else:
            # Use the move_to_end method to simulate the get operation
            return self.cache.move_to_end(key)

# Example usage:
# cache = LRUCache(3)
# cache.put(1, 10)
# cache.put(2, 20)
# print(cache.get(1))  # returns 10
# cache.put(3, 30)
# cache.put(4, 40)  # evicts key 2
# print(cache.get(2))  # returns -1 (cache item was evicted)
```

This implementation uses an `OrderedDict` to maintain the order of insertion, which helps in identifying the least recently used item efficiently. The `get` method returns the value associated with the key if it exists, otherwise, it returns `-1`. The `put` method updates the cache with a new key-value pair, evicting the least recently used item if the cache exceeds its capacity. The `__call__` method is overridden to allow the cache to be called like a function to simulate the `get` operation.

